WITH enriched AS (SELECT id, promo_code, starts_on, ends_on, discount_pct, MIN(discount_pct) OVER w_grp AS running_min_discount_pct, MAX(discount_pct) OVER w_grp AS running_max_discount_pct, SUM(discount_pct) OVER w_grp AS running_sum_discount_pct, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct FROM promotions WHERE MONTH(starts_on) IN (3, 4, 10) WINDOW w_grp AS (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, promo_code, starts_on, ends_on, discount_pct, running_max_discount_pct, running_sum_discount_pct, running_discount_pct FROM enriched ORDER BY discount_pct DESC NULLS LAST, running_discount_pct DESC
